 const motionOff=host=>{let saved=false;try{saved=environment.localStorage?.getItem('cji-mind-animation')==='off';}catch{}return environment.matchMedia?.('(prefers-reduced-motion: reduce)').matches||host.closest('[data-motion="off"]')||saved;};
 function announce(host,s){const page=host.querySelector('[data-hud-panel="'+s.page+'"]');host.querySelector('[data-hud-announcement]').textContent=page?.getAttribute('aria-label')??'';}
