 function read(mode,token){return load(mode,token).catch(()=>{if(token===generation&&root)for(const h of root.querySelectorAll('[data-mind-hud]'))if(h.dataset.hudMode===mode&&(!h._hudMetrics||h._hudMetrics.status==='FETCH_FAILED'))hydrate(h,{status:'FETCH_FAILED',reason:'지표를 불러오지 못했습니다.'});});}
