  bind('change',event=>{if(!event.target.matches?.('[data-hud-range]'))return;const host=event.target.closest('[data-mind-hud]'),s=state(host);s.range=event.target.value;host.querySelector('[data-hud-panel="3"]').innerHTML=chartPanel(host._hudMetrics,s.series,s.range);reveal(host,s);});
  bind('keydown',event=>{if(!event.target.matches?.('[data-hud-go],[data-hud-open]')||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const host=event.target.closest('[data-mind-hud]'),s=state(host);event.preventDefault();go(host,event.key==='Home'?0:event.key==='End'?3:s.page+(['ArrowDown','ArrowRight'].includes(event.key)?1:-1),{fromGesture:true});host.querySelector('[data-hud-go="'+state(host).page+'"]')?.focus({preventScroll:true});});
  bind('wheel',event=>{const host=event.target.closest?.('[data-mind-hud]');if(!host||event.target.closest('select,input,textarea')||Math.abs(event.deltaX)>=Math.abs(event.deltaY))return;const s=state(host),direction=Math.sign(event.deltaY),next=s.page+direction;if(Date.now()<s.wheelUntil){event.preventDefault();return;}if(next<0||next>3)return;event.preventDefault();const now=Date.now();if(s.wheelDirection!==direction||now-(s.wheelAt??0)>numberToken('--hud-wheel-settle-ms',host))s.wheelDelta=0;s.wheelDirection=direction;s.wheelAt=now;s.wheelDelta=(s.wheelDelta??0)+Math.abs(event.deltaY);if(s.wheelDelta<numberToken('--hud-wheel-threshold',host))return;s.wheelDelta=0;s.wheelUntil=Date.now()+numberToken('--hud-transition-ms',host)+numberToken('--hud-wheel-settle-ms',host);go(host,next,{fromGesture:true});},{passive:false});
